"""Serve the built front end against a synthetic book, model and SHAP cache.

This is the server the browser tests run against (``frontend/playwright.config.ts``).
Nothing here reads or writes ``data/``, ``artifacts/`` or ``reports/``:

* the customers are generated by the test suite's own ``make_synthetic_raw``, with
  every ID prefixed ``E2E-`` (the batch demo file's ``DEMO-`` rows never match one);
* the model is trained on them with one grid point per family;
* every path of the configuration points into one temporary folder, and that is
  checked before anything is written (``within``, then ``confine`` on the loaded
  configuration).

The API itself is the real one, middleware included; only its configuration
differs, through ``CHURNSENSE_CONFIG``. No final evaluation is ever recorded, so
the test partition stays withheld exactly as it does for the real model.

    .venv/bin/python scripts/e2e_server.py [--port 8799] [--public]

With ``--public`` it serves as the deployed demo does: after the model is
trained, the "dataset"'s aggregates are published (``churnsense.demo.build``),
then the dataset file and ``make explain``'s cache are **deleted** and the
service is started as ``deployment: {mode: public_demo, customer_records:
synthetic}``. What it lists is generated ``DEMO-`` customers; no ``E2E-``
customer is in its reach, and the browser tests assert none is ever shown.

It serves ``frontend/dist``, so build first (``make frontend``). The temporary
folder is removed when the server stops (SIGTERM or Ctrl-C).
"""

from __future__ import annotations

import argparse
import copy
import dataclasses
import os
import signal
import sys
import tempfile
from pathlib import Path
from typing import TYPE_CHECKING, Any

import yaml

if TYPE_CHECKING:
    import pandas as pd

ROOT = Path(__file__).resolve().parents[1]
# The generator lives with the tests (tests/conftest.py), which are not installed.
sys.path.insert(0, str(ROOT))

from churnsense.config import (  # noqa: E402
    DEFAULT_CONFIG_PATH,
    DEFAULT_RATE_LIMITS,
    Config,
    load_config,
)

#: Every synthetic customer's ID starts with this; the e2e tests refuse a server
#: whose customers do not, so a server on real data is never tested by mistake.
ID_PREFIX = "E2E-"
#: One customer gets the longest ID the API accepts (32 characters), for layouts.
LONG_ID = ID_PREFIX + "X" * 28
DATASET_FILENAME = "synthetic_customers.csv"
DEFAULT_PORT = 8799
DEFAULT_ROWS = 2000
#: The public server's book. Its sweep is published only at cuts with twenty churners and
#: twenty stayers between any two, the threshold among them (E8). Below its threshold the
#: e2e model leaves about 7% of churners, so twenty there need about 300 churners in
#: validation. Measured 2026-11-12: 4,000 rows leave 12 (no safe cuts); 8,000 leave 33
#: and give 7 cuts, prepared in about 15 s.
PUBLIC_ROWS = 8000
DEFAULT_SEED = 11
#: The deployment a ``--public`` server states: the deployed demo's own.
PUBLIC_DEPLOYMENT = {"mode": "public_demo", "customer_records": "synthetic"}
PUBLIC_CONFIG = "public.yaml"

#: One point per model family: the pages need a trained model of each kind to
#: compare, not a tuned one, and a full grid would make every run slow.
GRIDS: dict[str, dict[str, list[Any]]] = {
    "logistic_regression": {"classifier__C": [1.0]},
    "random_forest": {
        "classifier__n_estimators": [100],
        "classifier__max_depth": [8],
        "classifier__min_samples_leaf": [5],
    },
    "hist_gradient_boosting": {
        "classifier__learning_rate": [0.1],
        "classifier__max_leaf_nodes": [15],
        "classifier__min_samples_leaf": [20],
        "classifier__l2_regularization": [0.0],
    },
}
#: A budget a test run never exhausts.
E2E_BUDGET = {"burst": 1000, "per_seconds": 0.001}
#: Every per-client budget the service has, raised for this server alone. The
#: whole browser suite - every test, both workers - reaches the API from one
#: address, 127.0.0.1, so to the service it is a single visitor: at the real
#: budgets (a burst of 30 queries, then two a second) one test's requests would
#: decide whether another's are answered. The limits themselves are tested in
#: pytest (tests/test_limits.py), against the real values.
#:
#: Named from ``DEFAULT_RATE_LIMITS``, so a budget added later is raised here too
#: and never makes the browser tests depend on their order again. This reaches
#: nothing but the temporary configuration file ``prepare`` writes: the
#: defaults, ``configs/config.yaml`` and ``configs/deploy.yaml`` are only read,
#: and this script is not in the deployment image.
RATE_LIMITS = {name: dict(E2E_BUDGET) for name, _ in DEFAULT_RATE_LIMITS}

#: The browsers the suite runs at once: Playwright's ``workers`` in
#: ``frontend/playwright.config.ts`` (``tests/test_e2e_server.py`` keeps the two
#: equal). Each is a client of its own, but all reach this server from
#: 127.0.0.1, which the in-flight cap (``middleware.MAX_CLIENT_REQUESTS``) counts
#: as one: two pages loading at once - an explorer page sends about eight requests
#: - then share one browser's slots, and under load, when each request is held
#: longer, the second gets 429 ``too_many_in_flight``. So this server alone allows
#: that one address the slots of as many browsers as share it: each still has
#: exactly the production cap, which ``tests/test_limits.py`` tests as it is.
E2E_CLIENTS = 2


def in_flight_cap() -> int:
    """The in-flight cap for the one address every browser of the suite shares."""
    from churnsense.api import middleware

    return middleware.MAX_CLIENT_REQUESTS * E2E_CLIENTS


def synthetic_customers(rows: int, seed: int) -> pd.DataFrame:
    """The test suite's synthetic customers, re-identified ``E2E-00000``, ... and one long ID."""
    from tests.conftest import make_synthetic_raw

    from churnsense.data import schema

    frame = make_synthetic_raw(n=rows, seed=seed)
    ids = [f"{ID_PREFIX}{i:05d}" for i in range(rows)]
    ids[0] = LONG_ID
    frame[schema.ID_COLUMN] = ids
    return frame


def e2e_config(base: dict[str, Any], root: Path, *, sha256: str, rows: int) -> dict[str, Any]:
    """The repository's configuration with every path under ``root`` and a small training run."""
    conf = copy.deepcopy(base)
    conf["paths"] = {
        name: str(within(root, name, relative)) for name, relative in base["paths"].items()
    }
    conf["dataset"].update(filename=DATASET_FILENAME, sha256=sha256, expected_rows=rows)
    conf["training"].update(n_jobs=1, cv_folds=3, grids=copy.deepcopy(GRIDS))
    conf["training"]["calibration"]["cv_folds"] = 3
    conf["api"]["rate_limits"] = copy.deepcopy(RATE_LIMITS)
    conf["logging"]["level"] = "WARNING"
    return conf


def within(root: Path, name: str, relative: str) -> Path:
    """``root / relative``, resolved; refused unless it stays inside ``root``.

    Checked before anything is written there: an absolute or ``..`` path in the
    repository's configuration would otherwise place a file outside the folder.
    """
    path = (root / relative).resolve()
    if not path.is_relative_to(root.resolve()):
        raise ValueError(f"{name} = {relative} leaves {root}")
    return path


def outside_repository(root: Path) -> Path:
    """``root``, resolved; refused when it lies inside the repository (a TMPDIR set there)."""
    resolved = root.resolve()
    if resolved.is_relative_to(ROOT):
        raise ValueError(f"the temporary folder {resolved} is inside the repository")
    return resolved


def confine(cfg: Config, root: Path) -> None:
    """Refuse a configuration that could read or write anything outside ``root``."""
    root = outside_repository(root)
    paths = {field.name: getattr(cfg.paths, field.name) for field in dataclasses.fields(cfg.paths)}
    paths["dataset"] = cfg.raw_data_file
    for name, path in paths.items():
        if not path.is_absolute() or not path.resolve().is_relative_to(root):
            raise ValueError(f"{name} = {path} is outside {root}")


def prepare(root: Path, *, rows: int, seed: int) -> Config:
    """Write the synthetic dataset and configuration under ``root``, then train and cache."""
    from churnsense import analysis
    from churnsense.data import schema
    from churnsense.data.download import sha256_of
    from churnsense.data.loader import features_and_target, load_clean
    from churnsense.data.split import make_splits
    from churnsense.explainability.shap_explain import compute_and_cache
    from churnsense.models.train import save_artifact, train_all

    root = outside_repository(root)
    base = yaml.safe_load(DEFAULT_CONFIG_PATH.read_text(encoding="utf-8"))
    raw_dir = within(root, "raw_dir", base["paths"]["raw_dir"])
    raw_dir.mkdir(parents=True)
    dataset = raw_dir / DATASET_FILENAME
    synthetic_customers(rows, seed).to_csv(dataset, index=False)

    config_file = root / "config.yaml"
    config_file.write_text(
        yaml.safe_dump(e2e_config(base, root, sha256=sha256_of(dataset), rows=rows)),
        encoding="utf-8",
    )
    os.environ["CHURNSENSE_CONFIG"] = str(config_file)
    load_config.cache_clear()
    cfg = load_config()
    confine(cfg, root)

    cfg.paths.ensure()
    customers, cleaning = load_clean(cfg)
    X, y = features_and_target(customers, cfg)
    splits = make_splits(X, y, cfg)
    outcome = train_all(splits.X_train, splits.y_train, splits.X_val, splits.y_val, cfg=cfg)
    save_artifact(
        outcome,
        cfg.paths.artifacts_dir,
        cfg,
        data_sha256=cleaning.source_sha256,
        split_digest=splits.digest(),
    )
    reports = cfg.paths.reports_dir
    outcome.comparison_frame().to_csv(reports / "model_comparison.csv", index=False)
    training_rows = customers.loc[splits.X_train.index].drop(columns=[schema.ID_COLUMN])
    analysis.association_ranking(training_rows).to_csv(
        reports / "association_ranking.csv", index=False
    )
    compute_and_cache(cfg, sample=30)
    return cfg


def publish(root: Path, cfg: Config) -> Config:
    """Turn the prepared folder into a public demo's: aggregates in, the dataset out.

    The evidence is built from the folder's dataset exactly as ``make demo-data``
    builds it. Then the dataset file and the cache of its validation rows are
    removed, and a second configuration - the same one, stating the public
    deployment - becomes the one in force. Nothing outside ``root`` is touched:
    every path is checked before the first file is written or removed.
    """
    from churnsense.demo import build

    root = outside_repository(root)
    confine(cfg, root)
    held = (cfg.raw_data_file, cfg.paths.shap_cache_file)
    for path in held:  # a link inside the folder may still point out of it
        if not path.resolve().is_relative_to(root):
            raise ValueError(f"{path} is outside {root}")
    build.publish(cfg, sample=30)
    for path in held:
        path.unlink()
    stated = yaml.safe_load((root / "config.yaml").read_text(encoding="utf-8"))
    stated["deployment"] = dict(PUBLIC_DEPLOYMENT)
    config_file = root / PUBLIC_CONFIG
    config_file.write_text(yaml.safe_dump(stated), encoding="utf-8")
    os.environ["CHURNSENSE_CONFIG"] = str(config_file)
    load_config.cache_clear()
    public = load_config()
    confine(public, root)
    return public


def serve(root: Path, port: int, *, public: bool = False) -> None:
    """Check the served model and book come from ``root``, then serve until stopped."""
    import uvicorn

    from churnsense.api import main, state
    from churnsense.evaluation import release

    # The synthetic server shows no release, whatever the repository's own ledger holds.
    release.LEDGER_FILE = root / "governance" / release.LEDGER_FILE.name
    release.LEDGER_FILE.parent.mkdir(exist_ok=True)
    release.LEDGER_FILE.write_text(release.open_ledger_text(), encoding="utf-8")

    dashboard = state.get_dashboard()
    if not dashboard.model.source.resolve().is_relative_to(root.resolve()):
        raise RuntimeError(f"the served model {dashboard.model.source} is not the synthetic one")
    if dashboard.book.withheld is not None:
        raise RuntimeError(f"the synthetic book withholds its outcomes: {dashboard.book.withheld}")
    if dashboard.synthetic is not public:
        raise RuntimeError("the served book is not the one this server was asked for")
    if public and listed_dataset_customers(dashboard.frame):
        raise RuntimeError("a public server is listing the dataset's customers")
    from churnsense.api import middleware

    # This process only: the browsers share one address (``E2E_CLIENTS``).
    middleware.MAX_CLIENT_REQUESTS = in_flight_cap()
    uvicorn.run(
        main.app,
        host="127.0.0.1",
        port=port,
        proxy_headers=False,
        log_level="warning",
        access_log=False,
    )


def listed_dataset_customers(frame: pd.DataFrame) -> int:
    """How many listed customers carry the "dataset"'s ID prefix: none, on a public server."""
    from churnsense.data import schema

    return int(frame[schema.ID_COLUMN].str.startswith(ID_PREFIX).sum())


def _stop(signum: int, _frame: object) -> None:
    """Turn SIGTERM into SystemExit, so the temporary folder is removed on the way out.

    uvicorn shuts down gracefully on SIGTERM and then raises it again for the
    handler it found; Python's default handler would end the process before the
    ``with`` block below could clean up.
    """
    raise SystemExit(128 + signum)


def rows_for(rows: int | None, *, public: bool) -> int:
    """The rows asked for, or the default for the kind of server: see ``PUBLIC_ROWS``."""
    if rows is not None:
        return rows
    return PUBLIC_ROWS if public else DEFAULT_ROWS


def main(argv: list[str] | None = None) -> None:
    parser = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    parser.add_argument("--port", type=int, default=int(os.getenv("E2E_PORT", DEFAULT_PORT)))
    parser.add_argument(
        "--rows",
        type=int,
        default=None,
        help=f"default {DEFAULT_ROWS}; {PUBLIC_ROWS} with --public",
    )
    parser.add_argument("--seed", type=int, default=DEFAULT_SEED)
    parser.add_argument(
        "--public",
        action="store_true",
        help="serve as the deployed demo does: generated customers, no dataset in reach",
    )
    args = parser.parse_args(argv)

    if not (ROOT / "frontend" / "dist" / "index.html").is_file():
        raise SystemExit("frontend/dist is missing: run `make frontend` first")
    if load_config.cache_info().currsize:
        raise SystemExit("the configuration was read before the synthetic one was set")
    os.environ.setdefault("MPLBACKEND", "Agg")
    signal.signal(signal.SIGTERM, _stop)
    with tempfile.TemporaryDirectory(prefix="churnsense-e2e-") as folder:
        root = Path(folder)
        cfg = prepare(root, rows=rows_for(args.rows, public=args.public), seed=args.seed)
        if args.public:
            publish(root, cfg)
        serve(root, args.port, public=args.public)


if __name__ == "__main__":
    main()
